<script setup>
import {computed,inject,onMounted,onUnmounted,ref} from 'vue'
import {api} from '../api.js'
import {checkLabels,ratioText} from '../trusted-results.js'
const work=inject('workspace'),cal=inject('calibration'),rag=inject('retrieval')
const data=ref({domains:[],batches:[],jobs:[],schedules:[],sampling_plans:[]}),busy=ref(false),error=ref(''),notice=ref('')
const sourceRuns=ref([]),sourceRunId=ref(''),importMode=ref('saved')
const templateNames={POLICY_RAG:'按店铺规则回答',MISSING_KNOWLEDGE:'资料不够时说明并求助',CLARIFICATION:'缺少条件时先追问'}
const tab=ref('import'),domainId=ref(''),content=ref(''),format=ref('json'),mapping=ref({}),preview=ref(null),historyMode=ref('NECESSARY')
const batchName=ref('导入的 Agent 回答'),actor=ref(''),scopeReason=ref(''),scopeConfirmed=ref(false),parentBatch=ref(null),selectedBatch=ref('')
const selectedJob=ref(null),sampling=ref(null),randomCount=ref(5),reviewId=ref(''),reviewState=ref('EVIDENCE_INSUFFICIENT'),reviewReason=ref('')
const rulesOpen=ref(false),rubricOpen=ref(false),domainForm=ref({domain_id:'after_sales',name:'售后政策问答',business_scope:'售后政策咨询；排除商品推荐等其他业务咨询',template_id:'POLICY_RAG',agent_kind:'RAG',judge_prompt:null,rules:{},max_attempts:2}),rubric=ref(null)
const scheduleHour=ref(9),scheduleMinute=ref(0),scheduleTimezone=ref('Asia/Shanghai'),scheduleName=ref('每日评测'),dailyConfirmed=ref(false)
const compareLeft=ref(''),compareRight=ref(''),comparison=ref(null)
const domain=computed(()=>data.value.domains.find(d=>d.domain_id===domainId.value))
const batches=computed(()=>data.value.batches.filter(b=>b.domain_id===domainId.value))
const jobs=computed(()=>data.value.jobs.filter(j=>j.domain_id===domainId.value).sort((a,b)=>b.created_at.localeCompare(a.created_at)))
const labels={source_type:'题目来源类型',sample_id:'样本编号',question:'用户问题',answer:'客服实际回答',context:'对话历史',reference_policy:'参考政策',retrieved_evidence:'当时检索结果',reference_complete:'参考是否完整',conversation_id:'会话编号',turn_id:'当前轮次',object_ids:'业务对象',question_time:'提问时间',question_timezone:'时区',business_domain:'业务域',tools:'工具调用',tool_results:'工具结果',family_id:'问题族',error_type:'错误类型',tool_expectations:'工具预期条件'}
const stageLabels={QUEUED:'排队中',RUNNING:'运行中',COMPLETE:'运行结束',PARTIAL:'部分完成',FAILED:'运行失败',CANCEL_REQUESTED:'等待当前请求结束后取消',CANCELLED:'已取消',WAITING_CREDENTIALS:'等待恢复模型连接'}
async function act(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=importError(e.message)||'操作未完成，请检查输入。'}finally{busy.value=false}}
async function reload(){
 const [overview,history]=await Promise.all([api.get('/operations/overview'),api.get('/retrieval-history')])
 // Release bookkeeping is retained on disk, but is not a learner's evaluation category.
 data.value={...overview,domains:overview.domains.filter(d=>d.domain_id!=='release_memory_handoff')}
 if(!data.value.domains.some(d=>d.domain_id===domainId.value))domainId.value=data.value.domains[0]?.domain_id||''
 sourceRuns.value=history.filter(r=>r.status!=='RUNNING').sort((a,b)=>b.created_at.localeCompare(a.created_at))
 if(!sourceRuns.value.some(r=>r.run_id===sourceRunId.value))sourceRunId.value=rag.state.retest?.run.run_id||rag.state.baseline?.run.run_id||sourceRuns.value[0]?.run_id||''
}
function sourceLabel(r){const current=r.run_id===rag.state.baseline?.run.run_id||r.run_id===rag.state.retest?.run.run_id;return `${current?'当前实验 · ':''}${r.run_type==='BASELINE'?'初测':'复测'} · ${r.name} · ${new Date(r.created_at).toLocaleString('zh-CN')}`}
const explanations={QUESTION_OR_ANSWER_MISSING:'没有找到问题或回答，请检查下面的对应列名',QUESTION_OR_ANSWER_TOO_LARGE:'问题或回答过长，需要缩短后重新导入',CONTEXT_FORMAT_INVALID:'对话历史格式不正确',SELECTED_HISTORY_TOO_LARGE:'选中的对话历史过长',EVIDENCE_TOO_LARGE:'参考资料过多或过长',OBJECT_FORMAT_INVALID:'业务对象信息格式不正确',TOOL_FORMAT_INVALID:'工具记录格式不正确',TOOL_RESULT_ID_MISSING:'工具结果缺少对应编号',TOOL_RESULT_LINK_INVALID:'工具调用与结果无法一一对应',TOOL_CALL_ID_MISSING:'工具调用缺少编号',TOOL_CALL_ID_DUPLICATED:'工具调用编号重复',TOOL_RESULT_WITHOUT_CALL:'工具结果没有对应的调用',RANDOM:'随机抽中',FAILURE_OR_ABSTENTION:'未通过或资料不足',HUMAN_DISAGREEMENT:'人工与模型判断不同',CRITICAL_ERROR:'存在关键错误',BOUNDARY_SCORE:'评分接近边界',EVIDENCE_OR_SCOPE_CHANGED:'参考资料或评测范围改变',RUBRIC_OR_JUDGE_PROMPT_CHANGED:'评分规则或评分要求改变',JUDGE_CONFIGURATION_CHANGED:'评分模型设置改变',RESULT_RECONCILIATION_INCOMPLETE:'尚有结果缺失或重复',IMPROVED:'由不通过变为通过',REGRESSED:'由通过变为不通过',STILL_FAIL:'仍未通过',UNCHANGED:'判定相同',NOT_COMPARABLE:'条件不足，无法比较'}
function explain(code){return explanations[code]||(code?.startsWith('TOOL_SCOPE_UNKNOWN_OR_MISMATCH')?'工具记录与本题的对象或时间不一致':'材料存在需要核对的问题，请展开原始记录查看')}
function importError(message){return ({IMPORT_TOO_LARGE:'导入内容超过大小限制，请控制在 5 MiB 内。',IMPORT_RECORDS_INVALID:'每次请导入 1–100 条问题与回答。',IMPORT_CSV_HEADERS_INVALID:'表格第一行需要填写列名，且不能重复。',IMPORT_EVIDENCE_INVALID:'参考资料格式无法识别，请按示例填写。',RAG_SOURCE_NO_ANSWERS:'这次评测没有保存可导入的回答，请选择已完成回答评测的记录。'})[message]||(/^[A-Z][A-Z0-9_: -]+$/.test(message||'')?'操作未完成，请检查所选评测是否包含已保存的回答，以及材料是否填写完整。':message)}
async function sync(){await reload();if(selectedJob.value)selectedJob.value=await api.get('/operations/jobs/'+selectedJob.value.job.job_id)}
defineExpose({sync})
onMounted(()=>act(reload))
const timer=setInterval(async()=>{if(!selectedJob.value||busy.value)return;if(['QUEUED','RUNNING','CANCEL_REQUESTED'].includes(selectedJob.value.job.status)){try{selectedJob.value=await api.get('/operations/jobs/'+selectedJob.value.job.job_id);sampling.value=selectedJob.value.sampling_plans?.at(-1)||null;await reload()}catch{}}},2500)
onUnmounted(()=>clearInterval(timer))
function resetPreview(){preview.value=null;scopeConfirmed.value=false}
async function file(event){const f=event.target.files?.[0];if(!f)return;if(f.size>5*1024*1024){error.value='文件不能超过 5 MiB。';return}content.value=await f.text();format.value=f.name.endsWith('.csv')?'csv':f.name.endsWith('.jsonl')?'jsonl':'json';resetPreview();event.target.value=''}
function example(){content.value=JSON.stringify([
 {sample_id:'return_01',question:'定制商品可以七天无理由退货吗？',answer:'定制商品不适用七天无理由退货；质量问题可申请核验。',business_domain:domainId.value,reference_complete:true,reference_policy:[{evidence_id:'return-policy',text:'定制商品不适用七天无理由退货。质量问题请提供订单和照片核验。'}],retrieved_evidence:[{evidence_id:'chunk-1',text:'定制商品不适用七天无理由退货。质量问题请提供订单和照片核验。'}],family_id:'custom_returns'},
 {sample_id:'unknown_02',question:'签收30天后还能退货吗？',answer:'可以，所有商品都支持30天退货。',business_domain:domainId.value,reference_complete:false,family_id:'return_window'},
 {sample_id:'outside_03',question:'推荐一款新手机',answer:'请告诉我预算。',business_domain:'recommendation',family_id:'recommendation'}],null,2);format.value='json';mapping.value={};parentBatch.value=null;resetPreview()}
async function fromRag(id){await act(async()=>{const source=await api.get('/operations/rag-source/'+id);if(!source.records?.length)throw new Error('这次评测没有保存可导入的回答，请选择完成过回答评测的记录。');content.value=JSON.stringify(source.records,null,2);format.value='json';mapping.value={};parentBatch.value=null;preview.value=await api.post('/operations/preview',{domain_id:domainId.value,content:content.value,format:'json',mapping:{},history_mode:historyMode.value});scopeConfirmed.value=false;notice.value='已导入原问题、原回答和当时使用的资料。请在下面核对评测范围和资料是否齐全；导入不会调用模型。'})}
async function inspect(){await act(async()=>{preview.value=await api.post('/operations/preview',{domain_id:domainId.value,content:content.value,format:format.value,mapping:mapping.value,history_mode:historyMode.value});scopeConfirmed.value=false})}
async function saveBatch(){await act(async()=>{if(!scopeConfirmed.value||!preview.value)throw new Error('先预览并确认范围。');const batch=await api.post('/operations/batches',{domain_id:domainId.value,content:content.value,format:format.value,mapping:mapping.value,history_mode:historyMode.value,name:batchName.value,confirmed_by:actor.value,confirmation_reason:scopeReason.value,parent_batch_id:parentBatch.value,preview_hash:preview.value.preview_hash,decisions:preview.value.records.map(r=>({sample_id:r.sample_id,state:r.scope.state,reason:r.scope.reason,reference_complete:r.reference_complete,family_id:r.family_id,error_type:r.error_type}))});selectedBatch.value=batch.batch_id;await reload();tab.value='runs';notice.value='已保存冻结输入。排除、缺失和清洗记录均已保留。'})}
async function repair(id){await act(async()=>{const batch=await api.get('/operations/batches/'+id);domainId.value=batch.domain_id;content.value=JSON.stringify(batch.raw_records,null,2);format.value='json';mapping.value=batch.mapping;parentBatch.value=id;batchName.value=batch.name+' · 取证修订';tab.value='import';importMode.value='external';resetPreview();notice.value='修订会生成带父引用的新批次；原问题和实际回答保持固定，旧标注不继承。'})}
async function saveDomain(){await act(async()=>{const value=await api.post('/operations/domains',{...domainForm.value,...(rubric.value?{rubric:rubric.value}:{})});domainId.value=value.domain_id;await reload();notice.value='已保存业务规则新版本；已有批次和运行继续使用各自冻结版本。';rulesOpen.value=false})}
function editDomain(){domainForm.value=JSON.parse(JSON.stringify(domain.value));for(const k of ['profile_id','version','content_hash','created_at','schema_version','evidence_contract_version'])delete domainForm.value[k];rubric.value=domainForm.value.rubric;delete domainForm.value.rubric;rulesOpen.value=true}
async function start(){await act(async()=>{if(!work.state.session)throw new Error('请先连接模型。');selectedJob.value=await api.post('/operations/jobs',{batch_id:selectedBatch.value,provider_session_id:work.state.session.provider_session_id,request_id:crypto.randomUUID()});await reload()})}
async function openJob(id){await act(async()=>{selectedJob.value=await api.get('/operations/jobs/'+id);tab.value='runs';reviewId.value='';sampling.value=selectedJob.value.sampling_plans?.at(-1)||null})}
async function jobAction(action){await act(async()=>{await api.post('/operations/jobs/'+selectedJob.value.job.job_id+'/'+action,{});selectedJob.value=await api.get('/operations/jobs/'+selectedJob.value.job.job_id);sampling.value=selectedJob.value.sampling_plans?.at(-1)||null;await reload()})}
async function saveReview(id){await act(async()=>{await api.post('/operations/jobs/'+selectedJob.value.job.job_id+'/reviews',{sample_id:id,evaluation_state:reviewState.value,reason:reviewReason.value,actor:actor.value});selectedJob.value=await api.get('/operations/jobs/'+selectedJob.value.job.job_id);reviewId.value='';reviewReason.value=''})}
async function drawSample(){await act(async()=>{sampling.value=await api.post('/operations/jobs/'+selectedJob.value.job.job_id+'/sampling',{count:randomCount.value,seed:crypto.randomUUID()});await reload()})}
async function toCalibration(id){await act(async()=>{const dataset=await api.post('/operations/sampling/'+id+'/calibration',{actor:actor.value});await cal.restore();cal.state.actor=actor.value;await cal.openDataset(dataset.dataset_id);cal.go(2);work.go('calibration');work.state.notice='已建立校准数据集 '+dataset.name+'。请在校准页选择这份数据，完成真实人工标注；已查看机评的复核不算独立盲标。'})}
async function download(){await act(async()=>{const f=await api.download('/operations/jobs/'+selectedJob.value.job.job_id+'/export');const u=URL.createObjectURL(f.blob),a=document.createElement('a');a.href=u;a.download=f.filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)})}
async function saveSchedule(){await act(async()=>{if(!dailyConfirmed.value)throw new Error('请确认自动运行的输入和调用预算。');await api.post('/operations/schedules',{domain_id:domainId.value,batch_id:selectedBatch.value,provider_session_id:work.state.session.provider_session_id,name:scheduleName.value,timezone:scheduleTimezone.value,hour:scheduleHour.value,minute:scheduleMinute.value,enabled:true});await reload();notice.value='已保存产品内的日级计划。服务器运行且模型凭据可用时执行。'})}
async function disableSchedule(item){await act(async()=>{const p=item.plan;await api.post('/operations/schedules',{domain_id:p.domain_id,batch_id:p.batch_id,provider_session_id:p.provider_session_id,name:p.name,timezone:p.timezone,hour:p.hour,minute:p.minute,enabled:false,replaces_plan_id:p.plan_id});await reload()})}
async function compare(){await act(async()=>{comparison.value=await api.get('/operations/compare?left='+compareLeft.value+'&right='+compareRight.value)})}
</script>
<template>
 <div class="page-heading"><div><p class="eyebrow">评测已有 Agent 回答</p><h1>先选已有回答，再检查答得好不好。</h1><p>这里检查已经答过的话：先选一次评测，再核对资料，最后评分与复核。想修改客服并让它重新作答，请回到主实验。</p></div></div>
 <details class="panel"><summary>第一次用：这里和主实验、评分标准有什么区别？</summary><p>主实验让客服重新回答，验证修改有没有效果。这里固定原回答，检查它当时答得好不好。评分标准规定什么算好；评测校准则把模型判定与人工判断对照，检查打分是否可靠。</p><p>先选回答 → 核对资料 → 评分与复核。每日计划会重复检查选定批次；新聊天记录需要另行导入。</p></details>
 <p><a href="/evaluation-guide.html" target="_blank" rel="noopener">查看完整新手说明：用途、步骤和术语例子 ↗</a></p>
 <p v-if="error" class="note danger" role="alert">{{error}}</p><p v-if="notice" class="note positive" role="status">{{notice}}</p><p v-if="busy" role="status">正在处理…</p>
 <section class="panel"><div class="form-row"><label>评测分类（业务域）<select aria-label="评测分类" v-model="domainId" @change="resetPreview"><option value="">先建立评测分类</option><option v-for="d in data.domains" :key="d.domain_id" :value="d.domain_id">{{d.name}} · 第 {{d.version}} 版</option></select></label><label>当前操作人<input v-model="actor" placeholder="填写姓名或昵称，方便知道谁核对了结果" /></label></div><p v-if="domain">{{domain.business_scope}}。评分方式：{{templateNames[domain.template_id]||'自定义评分规则'}} · 第 {{domain.version}} 版。</p><p class="muted">评测分类用来分开不同业务的规则，例如售后和配送。版本表示第几次保存规则，旧评测仍保留当时的版本。</p><div class="button-row"><button class="secondary" @click="rulesOpen=!rulesOpen">建立评测分类</button><button v-if="domain" class="secondary" @click="editDomain">修订当前规则</button></div>
 <form v-if="rulesOpen" @submit.prevent="saveDomain"><h2>业务规则与评分版本</h2><div class="form-row"><label>分类编号（用于保存记录）<input v-model="domainForm.domain_id" placeholder="例如 after_sales，只用字母、数字或下划线" pattern="[A-Za-z0-9_-]{1,80}" required /></label><label>名称<input v-model="domainForm.name" required /></label></div><label>业务范围与排除说明<textarea v-model="domainForm.business_scope" required /></label><div class="form-row"><label>场景模板<select v-model="domainForm.template_id"><option value="POLICY_RAG">按店铺规则回答</option><option value="MISSING_KNOWLEDGE">资料不够时说明并求助</option><option value="CLARIFICATION">缺少条件时先追问</option></select></label><label>被测能力<select v-model="domainForm.agent_kind"><option value="RAG">先查资料再回答</option><option value="TOOL_TRACE">已有业务工具轨迹</option></select></label><label>最多执行次数（包括重试）<input v-model.number="domainForm.max_attempts" type="number" min="1" max="5" /></label></div><details><summary>进阶：哪些工具信息需要保留</summary><p>评分时会保留商品描述等业务信息，移除给模型下指令的内部内容。只有接入外部工具日志、且某列被误当成内部指令时，才需要在这里填写原列名并重新预览。</p><label>必须作为业务数据保留的字段名（每行一个）<textarea :value="(domainForm.rules.preserve_tool_fields||[]).join('\n')" @input="domainForm.rules.preserve_tool_fields=$event.target.value.split('\n').map(v=>v.trim().toLowerCase()).filter(Boolean)" /></label></details><label>允许的兜底<textarea v-model="domainForm.rules.allowed_fallbacks" /></label><label>必要业务条件（每行一项）<textarea :value="(domainForm.rules.necessary_conditions||[]).join('\n')" @input="domainForm.rules.necessary_conditions=$event.target.value.split('\n').filter(Boolean)" /></label><label v-if="domainForm.agent_kind==='TOOL_TRACE'">本场景必要工具名称（每行一项）<textarea :value="(domainForm.rules.required_tools||[]).join('\n')" @input="domainForm.rules.required_tools=$event.target.value.split('\n').filter(Boolean)" /></label><details><summary>进阶：评分模型的要求与评分细则</summary><p>这里告诉评分模型如何打分，例如什么算遗漏、每一档分数的条件。留空即可使用初始规则。修改后建议用人工判过的题检查评分是否可靠；原回答不变。</p><label>给评分模型的要求<textarea v-model="domainForm.judge_prompt" rows="8" placeholder="留空使用默认片段引证协议" /></label><template v-if="rubric"><fieldset v-for="(d,key) in rubric.dimensions" :key="key"><legend>{{d.label}}</legend><label v-for="score in ['0','1','2']" :key="score">{{score}} 分条件<textarea v-model="d.anchors[score]" /></label><label>正例<textarea v-model="d.positive" /></label><label>反例<textarea v-model="d.negative" /></label><label>边界<textarea v-model="d.boundary" /></label><label>最低分<input v-model.number="rubric.rules.minimum_scores[key]" type="number" min="0" max="2" /></label></fieldset></template><p v-else>首次保存使用现有初始四维细则；保存后可打开“修订当前规则”编辑锚点和边界。</p></details><button class="primary" :disabled="busy">保存规则新版本</button></form></section>
 <div class="button-row"><button class="secondary" @click="tab='import'">1. 选择回答与核对资料</button><button class="secondary" @click="tab='runs'">2. 评分与人工复核</button><button class="secondary" @click="tab='daily'">3. 每日检查与前后对照</button><button class="text-button" @click="act(reload)">刷新记录</button></div>
 <section v-if="tab==='import'" class="panel"><h2>导入已有回答</h2>
 <p>已经在前面完成过评测？直接选取记录即可，系统会带入问题、回答和当时的资料。</p>
 <div class="button-row" aria-label="回答来源"><button :class="importMode==='saved'?'primary':'secondary'" @click="importMode='saved'">从之前的评测导入</button><button :class="importMode==='external'?'primary':'secondary'" @click="importMode='external'">导入外部文件或粘贴内容（可选）</button></div>
 <div v-if="importMode==='saved'" class="saved-source"><label>选择之前完成的评测<select v-model="sourceRunId" aria-label="选择之前完成的评测"><option value="">请选择一次评测</option><option v-for="r in sourceRuns" :key="r.run_id" :value="r.run_id">{{sourceLabel(r)}}</option></select></label><button class="primary" :disabled="busy||!domainId||!sourceRunId" @click="fromRag(sourceRunId)">导入这次评测的回答</button><p v-if="!sourceRuns.length" class="note">还没有完成的评测。先在主实验完成一次回答评测，再回到这里。</p><p v-if="!domainId" class="note">先在上面建立评测分类，例如“售后政策问答”，说明这次按什么业务规则检查。</p><p class="muted">读取已保存的原回答，不会重新作答或调用模型。没有执行的保留题不会导入；仅检查检索、未保存回答的评测不能用于此处。</p></div>
 <div v-else><p>用于导入其他系统的聊天记录。每批 1–100 条，可选择文件或直接粘贴，支持普通表格文件（CSV）和结构化记录（JSON、JSONL）。</p><input aria-label="选择日志文件" type="file" accept=".json,.jsonl,.csv" @change="file" /><label>文件格式<select v-model="format" @change="resetPreview"><option value="json">JSON：一组完整记录</option><option value="jsonl">JSONL：每行一条记录</option><option value="csv">CSV：第一行为列名的表格</option></select></label><label>日志内容<textarea v-model="content" rows="8" @input="resetPreview" /></label><button class="secondary" :disabled="!domainId" @click="example">载入演示日志</button>
 <details><summary>列名对应设置（字段映射，可选）</summary><p>字段就是一项信息，例如“问题”或“回答”。字段映射就是告诉系统：你的文件里，哪一列装的是这项信息。直接导入之前的评测不需要设置。</p><p>例如表格的两列叫“客户提问”和“客服回复”，就在下面“用户问题”填“客户提问”，“客服实际回答”填“客服回复”。如果文件已用默认列名，留空即可。</p><details><summary>什么是嵌套字段？看一个例子</summary><p>有些记录会把信息再放进一层。例如下面的问题放在“对话”里面，这就叫嵌套。此时在“用户问题”中填 <code>对话.问题</code>，小数点表示继续向里找一层。普通表格只填列名即可。</p><pre>{"对话":{"问题":"能退货吗？"},"客服回复":"请提供订单信息。"}</pre></details><div class="mapping-grid"><label v-for="(label,key) in labels" :key="key">{{label}}<input v-model="mapping[key]" :aria-label="label+'的原列名'" :placeholder="'留空使用默认列名：'+key" @input="resetPreview" /></label></div></details>
 <button class="primary" :disabled="busy||!domainId||!content" @click="inspect">预览并核对资料</button></div>
 <details v-if="content"><summary>进阶：对话历史与导入原文</summary><label>评分时带入多少对话历史<select v-model="historyMode" @change="resetPreview"><option value="NECESSARY">最近 4 条用户和客服消息</option><option value="FULL">提供的全部对话</option></select></label><p>用于理解“它”“上次”等说法。选择较短历史会省略更早的消息；原文仍保留。更改后请重新预览。</p><button v-if="!preview" class="secondary" @click="inspect">按当前历史范围重新预览</button><pre>{{content}}</pre></details>
 <template v-if="preview"><h3>输入 {{preview.processing.raw_count}} 条 → 去重后 {{preview.processing.unique_count}} 条</h3><p>完全一样的记录只保留一条；同一道问题的不同回答会分别保留。请核对下面的问题、回答、业务范围和参考资料。</p><p v-if="preview.processing.duplicates.length" class="note">完全重复记录：{{preview.processing.duplicates.map(r=>r.source_row+' → '+r.duplicate_of).join('；')}}</p><article v-for="r in preview.records" :key="r.sample_id" class="builder-card"><h3>{{r.sample_id}} · {{r.question}}</h3><p class="preserved-answer">{{r.answer}}</p><p v-if="r.issues.length" class="note warning">取证问题：{{r.issues.map(explain).join('；')}}</p><p v-if="r.provenance.removed_internal_fields.length">从评测材料隔离的内部字段：{{r.provenance.removed_internal_fields.join('；')}}</p><div class="form-row"><label>范围<select v-model="r.scope.state"><option value="PENDING">待确认</option><option value="INCLUDE">纳入当前业务</option><option value="EXCLUDE">排除其他业务的问题</option></select></label><label>纳入或排除依据<input v-model="r.scope.reason" /></label><label>参考资料是否齐全<select v-model="r.reference_complete"><option :value="null">未知</option><option :value="true">已核对，足够判定这题</option><option :value="false">缺少判定需要的资料</option></select></label></div><div class="form-row"><label>同类问题分组（可选）<input placeholder="例如：退货时限" v-model="r.family_id" /></label><label>问题标签（可选）<input placeholder="例如：漏掉商品限制" v-model="r.error_type" /></label></div><details><summary>查看业务证据与原始对应关系</summary><pre>{{JSON.stringify({reference:r.reference_policy,retrieved:r.retrieved_evidence,tools:r.tool_evidence,source:r.provenance},null,2)}}</pre></details></article><label>批次名称<input v-model="batchName" /></label><label>本次范围与取证确认说明<textarea v-model="scopeReason" /></label><p v-if="parentBatch">父批次 {{parentBatch}}；修订不继承旧人工复核。</p><label class="check"><input v-model="scopeConfirmed" type="checkbox" />我已逐条核对业务范围、参考完整性和取证变化</label><button class="primary" :disabled="busy||!scopeConfirmed||!actor.trim()||!scopeReason.trim()||preview.records.some(r=>r.scope.state==='PENDING')" @click="saveBatch">保存本批回答，准备评分</button></template></section>
 <section v-if="tab==='runs'" class="panel"><h2>固定回答评分</h2><label>输入批次<select v-model="selectedBatch"><option value="">选择已确认批次</option><option v-for="b in batches" :key="b.batch_id" :value="b.batch_id">{{b.name}} · {{b.created_at}}</option></select></label><div class="button-row"><button class="primary" :disabled="busy||!selectedBatch||work.state.session?.text_connection_status!=='READY'" @click="start">开始评分已有回答</button><button class="secondary" :disabled="!selectedBatch" @click="repair(selectedBatch)">建立取证修订批次</button></div><p>使用当前已连接模型，遵守该会话调用上限。每个业务域单独排队；重试保留调用记录，不增加独立样本数。</p><p v-if="!work.state.session" class="note">请先在“连接模型”保存并测试模型。</p>
 <button v-for="j in jobs" :key="j.job_id" class="history-row" @click="openJob(j.job_id)"><span>{{j.created_at}} · {{stageLabels[j.status]}} · 第 {{j.attempt}} 次执行</span><small>{{j.window.end?'日级窗口至 '+j.window.end:j.job_id.slice(0,8)}}</small></button>
 <template v-if="selectedJob"><h3>运行 {{selectedJob.job.job_id.slice(0,8)}} · {{stageLabels[selectedJob.job.status]}}</h3><p>覆盖：{{ratioText(selectedJob.summary.coverage)}}；通过：{{ratioText(selectedJob.summary.pass_rate)}}</p><p v-if="!selectedJob.summary.complete" class="note warning">本次不发布整批通过率。缺失 {{selectedJob.summary.missing_ids.join('、')||'无'}}，重复 {{selectedJob.summary.duplicate_ids.join('、')||'无'}}；记录 {{stageLabels[selectedJob.job.status]}}。</p><p>实际模型请求 {{selectedJob.summary.actual_requests??'总数未知'}} 次（已知至少 {{selectedJob.summary.known_request_minimum}} 次）；独立样本 {{selectedJob.summary.independent_samples}} 条；人工复核 {{selectedJob.summary.human_review_count}} 条。费用未知时不填零。</p><p v-if="!selectedJob.summary.request_accounting_complete" class="note warning">发生过 worker 中断，部分请求是否已到达模型服务无法确认；重试保留该限制，不把未知调用计为零。</p><p>范围外 {{selectedJob.summary.excluded.length}} 条；复核是在机评之后进行，不能当作独立人工校准。</p><div class="button-row"><button class="secondary" @click="download">导出逐题 CSV</button><button class="secondary" @click="openJob(selectedJob.job.job_id)">刷新结果</button><button v-if="['QUEUED','RUNNING'].includes(selectedJob.job.status)" class="secondary" @click="jobAction('cancel')">取消后续请求</button><button v-else class="secondary" :disabled="selectedJob.job.attempt>=selectedJob.job.rule_snapshot.max_attempts" @click="jobAction('retry')">重试执行失败或未运行的题</button></div>
 <article v-for="row in selectedJob.rows" :key="row.record.sample_id" class="builder-card"><h3>{{row.record.sample_id}} · {{checkLabels[row.evaluation_state]}}</h3><p>{{row.record.question}}</p><p class="preserved-answer">{{row.record.answer}}</p><p>{{row.review?.reason||row.event?.reason||'尚未形成结果'}}</p><p v-if="row.event?.input_package?.missing_items?.length" class="note warning">缺少：{{row.event.input_package.missing_items.join('；')}}</p><details v-if="row.event"><summary>评分、引用和工具检查</summary><pre>{{JSON.stringify({judgment:row.event.judgment,tool_checks:row.event.tool_checks,item_checks:row.event.input_package?.item_checks},null,2)}}</pre></details><button class="secondary" :disabled="!row.event" @click="reviewId=row.record.sample_id;reviewReason=''">人工复核本题</button><form v-if="reviewId===row.record.sample_id" @submit.prevent="saveReview(row.record.sample_id)"><label>人工判定<select v-model="reviewState"><option v-for="s in ['PASS','FAIL','EVIDENCE_INSUFFICIENT','NOT_APPLICABLE']" :key="s" :value="s">{{checkLabels[s]}}</option></select></label><label>复核依据<textarea v-model="reviewReason" required /></label><button class="primary" :disabled="busy||!actor.trim()">保存复核，保留原判</button></form></article>
 <h3>抽样复核与评分校准</h3><label>随机抽样数<input v-model.number="randomCount" type="number" min="1" max="100" /></label><button class="secondary" @click="drawSample">生成复核队列</button><p>随机样本之外另纳入失败、弃判、关键错误和人机分歧；队列保留抽样来源与分母。</p><template v-if="sampling"><p>来自 {{sampling.source_count}} 条，其中随机 {{sampling.random_count}} 条；合并去重后 {{sampling.selections.length}} 条。</p><p v-for="s in sampling.selections" :key="s.sample_id">{{s.sample_id}} · {{s.reasons.map(explain).join('、')}}</p><button class="secondary" :disabled="!actor.trim()" @click="toCalibration(sampling.plan_id)">送入人工校准流程</button></template></template></section>
 <section v-if="tab==='daily'" class="panel"><h2>每日检查与报告</h2><p>当前运行已确认的固定批次快照。新增或迟到的生产日志，需要先导入新批次，再更新计划；不会把重复回放的样本当作新增独立样本。</p><label>固定输入批次<select v-model="selectedBatch"><option value="">选择批次</option><option v-for="b in batches" :key="b.batch_id" :value="b.batch_id">{{b.name}}</option></select></label><label>计划名称<input v-model="scheduleName" /></label><div class="form-row"><label>时区<input v-model="scheduleTimezone" /></label><label>小时<input v-model.number="scheduleHour" type="number" min="0" max="23" /></label><label>分钟<input v-model.number="scheduleMinute" type="number" min="0" max="59" /></label></div><label class="check"><input v-model="dailyConfirmed" type="checkbox" />确认每日对所选批次调用当前模型评分，调用上限沿用模型配置</label><button class="primary" :disabled="!selectedBatch||!dailyConfirmed||!work.state.session||busy" @click="saveSchedule">保存每日计划</button><p>服务重启后，模型密钥需要重新输入；计划状态会提示等待连接，已有结果保留。</p><article v-for="item in data.schedules.filter(s=>s.plan.domain_id===domainId)" :key="item.plan.plan_id" class="builder-card"><h3>{{item.plan.name}} · {{item.plan.enabled?'启用':'停用'}}</h3><p>{{item.plan.timezone}} {{String(item.plan.hour).padStart(2,'0')}}:{{String(item.plan.minute).padStart(2,'0')}} · {{item.health==='READY'?'模型凭据可用':'等待恢复模型连接'}}</p><p v-if="item.missed_window_count" class="note warning">此前错过 {{item.missed_window_count}} 个窗口，尚未计为完成；请确认数据范围后补跑。</p><p>上次窗口：{{item.last_window_end||'尚未运行'}}。</p><p>批次 {{item.plan.batch_id}}；{{item.source_note}}</p><button v-if="item.plan.enabled" class="secondary" @click="disableSchedule(item)">停用计划</button></article><h3>窗口报告</h3><button v-for="j in jobs.filter(j=>j.window.end)" :key="j.job_id" class="history-row" @click="openJob(j.job_id)">{{j.window.start}} → {{j.window.end}} · {{stageLabels[j.status]}}</button>
 <h3>已有回答的前后重评</h3><div class="form-row"><label>修改前<select v-model="compareLeft"><option v-for="j in jobs" :key="j.job_id" :value="j.job_id">{{j.job_id.slice(0,8)}} · {{j.created_at}}</option></select></label><label>修改后<select v-model="compareRight"><option v-for="j in jobs" :key="j.job_id" :value="j.job_id">{{j.job_id.slice(0,8)}} · {{j.created_at}}</option></select></label></div><button class="secondary" :disabled="!compareLeft||!compareRight||compareLeft===compareRight" @click="compare">查看变化与限制</button><template v-if="comparison"><p class="note">{{comparison.limitation}}</p><p>条件变化：{{comparison.change_reasons.map(explain).join('；')||'未发现'}}；新增 {{comparison.scope_added.length}} 条，移除 {{comparison.scope_removed.length}} 条。</p><p v-for="p in comparison.pairs" :key="p.sample_id">{{p.sample_id}} · {{checkLabels[p.before]||'未纳入'}} → {{checkLabels[p.after]||'未纳入'}} · {{explain(p.transition)}}</p><details><summary>同类问题统计（原始记录）</summary><pre>{{JSON.stringify(comparison.families,null,2)}}</pre></details></template></section>
</template>
<style scoped>
.saved-source{padding:18px;background:var(--surface-soft);border-radius:12px}.saved-source select{max-width:100%}.mapping-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}.preserved-answer{white-space:pre-wrap;background:var(--surface-soft);padding:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}fieldset{margin:15px 0;padding:12px}.history-row{width:100%;text-align:left;margin:6px 0}.button-row{margin:14px 0}.builder-card{margin:15px 0;overflow-wrap:anywhere}input[type=file]{margin:16px 0}
</style>
